                logger.exception(
                    f"No active sql transaction while updating lastalert for `{alert.fingerprint}`, retry #{attempt}",
                    extra={
                        "alert_id": alert.id,
                        "tenant_id": tenant_id,
                        "fingerprint": alert.fingerprint,
                    },
                )
